    int n;
    cin >> n;

    unordered_set<long long> values;

    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        values.insert(x);
    }

    int longest = 0;

    for (long long x : values) {
        if (values.find(x - 1) == values.end()) {
            long long current = x;
            int length = 1;

            while (values.find(current + 1) != values.end()) {
                current++;
                length++;
            }

            longest = max(longest, length);
        }
    }

    cout << longest;

    return 0;
}

